import {createSeed,collections} from './data/index.js';
import {t,local,enumKey} from './i18n/index.js';
import {esc,download,csv,flattenRecord,safeStorage} from './utils.js';
import {parseDataset,validateDataset} from './validation.js';
import {person,art} from './illustrations.js';
import {freshJourney,entryPosition,getActions,resolveAction,commitResult,nextStage,changeTier,goBack,parseHash,shareHash,emphasis} from './journey.js';
import {presentationBar} from './presentation.js';
import {recordForm,readRecordForm,newRecord} from './editor.js';
const storage=safeStorage();
let data=createSeed();let recovery=false;
try{const saved=storage.get('w360-dataset-v1');if(saved)data=validateDataset(saved)}catch{recovery=true}
const remembered=storage.get('w360-session-v1');
let state={lang:'en',view:'home',journey:freshJourney(),presenter:null,menu:false,filter:{},sourceTab:false,editorCollection:'findings'};
if(remembered&&typeof remembered==='object'){
 state.lang=remembered.lang==='ar'?'ar':'en';
 const j=remembered.journey;
 if(j&&['gold','platinum','elite'].includes(j.tier)&&data.stages.some(s=>s.id===j.stage)&&Array.isArray(j.trail)){
  state.journey={...freshJourney(),...j,result:null,trail:j.trail.filter(e=>data.stages.some(s=>s.id===e.stage)&&['gold','platinum','elite'].includes(e.tier)).slice(-120)};
  if(!state.journey.profiles||typeof state.journey.profiles!=='object')state.journey.profiles={};
  if(!Array.isArray(state.journey.explored))state.journey.explored=[];
  if(!Array.isArray(state.journey.reviewed))state.journey.reviewed=[];
 }
}
if(location.hash){const p=parseHash(location.hash,data);state.lang=p.lang;state.view=p.view;state.journey=changeTier(state.journey,p.tier);state.journey.stage=p.stage;state.journey.mode=p.mode;state.journey.started=p.view==='journey';}
const root=document.querySelector('#app'),dialog=document.querySelector('#detail-dialog');
let dialogContext=null,returnFocus=null,lastMapPosition=null,toastTimer;
const L=v=>local(v,state.lang),T=k=>t(k,state.lang),E=v=>esc(L(v)),B=v=>T(enumKey[v]||v);
const by=(collection,id)=>data[collection].find(x=>x.id===id);
const channelName=id=>by('touchpoints',id)?L(by('touchpoints',id).title):id===null?'':T('unknown');
const ownerName=id=>L(by('owners',id)?.name||T('unassigned'));
const stageName=id=>L(by('stages',id)?.title||id);
const tierName=id=>L(by('tiers',id)?.name||id);
function badge(label,cls='neutral'){return `<span class="badge ${cls}">${esc(label)}</span>`}
const statusBadge=(status)=>badge(B(status),status==='validated'?'green':status==='historical'?'historical':status==='missing'||status==='unknown'?'outlined':'neutral');
function btn(action,label,cls='text-button',attrs=''){return `<button type="button" data-action="${action}" class="${cls}" ${attrs}>${esc(label)}</button>`}
function persist(dataset=false){if(dataset)storage.set('w360-dataset-v1',data);storage.set('w360-session-v1',{lang:state.lang,journey:{...state.journey,result:null}});}
function updateHash(){const h=shareHash(state);if(location.hash!==h)history.replaceState(null,'',h);}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4300);}
function visitStage(){const id=state.journey.tier+':'+state.journey.stage;if(!state.journey.explored.includes(id))state.journey.explored.push(id);}
function render(focusId){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.body.classList.toggle('paused',!!state.presenter?.paused);document.querySelector('#skip-link').textContent=T('skip');document.querySelector('#dialog-close').setAttribute('aria-label',T('close'));
 root.innerHTML=header()+`<main id="main" tabindex="-1">${({home:renderHome,journey:renderJourney,evidence:renderEvidence,gaps:renderGaps,plan:renderPlan,governance:renderGovernance,editor:renderEditor}[state.view]||renderHome)()}</main>`+footer();
 updateHash();persist();
 if(state.view==='journey'){const rawCurrent=state.journey.stage==='discover'&&state.journey.result?entryPosition(state.journey.result.channel):by('stages',state.journey.stage);const current={...rawCurrent,x:state.lang==='ar'?100-rawCurrent.x:rawCurrent.x};const avatar=document.querySelector('.customer-avatar');if(avatar){const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const old=lastMapPosition||current;avatar.style.left=old.x+'%';avatar.style.top=old.y+'%';requestAnimationFrame(()=>requestAnimationFrame(()=>{avatar.style.left=current.x+'%';avatar.style.top=current.y+'%';if(reduce)avatar.style.transition='none';}));lastMapPosition=current;}}
 if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});
}
function header(){const nav=['journey','evidence','gaps','plan','governance'];return `<header class="site-header"><div class="header-inner"><button class="brand" data-action="nav" data-view="home" aria-label="Wessam 360° · ${T('home')}"><span class="brand-name">Wessam<span class="brand-degree">360°</span></span><span class="brand-caption">${state.lang==='ar'?'وسام · منظور شامل للعلاقة':'A relationship in perspective'}</span></button><button class="mobile-menu" data-action="menu" aria-label="${T('sceneNavigation')}" aria-expanded="${state.menu}">☰</button><nav class="main-nav ${state.menu?'open':''}" aria-label="${T('sceneNavigation')}">${nav.map(v=>`<button data-action="nav" data-view="${v}" ${state.view===v?'aria-current="page"':''}>${T(v)}</button>`).join('')}</nav><div class="header-tools"><button data-action="nav" data-view="editor" class="editor-link ${state.view==='editor'?'active':''}" aria-label="${T('editor')}" title="${T('editor')}"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m9 3-1 3-3 1-2 4 2 3 1 3 4 3 4-1 3-1 3-4-1-4-1-3-4-2Z"/><circle cx="12" cy="12" r="3"/></svg></button><button id="language-toggle" data-action="language" class="language-toggle" lang="${state.lang==='en'?'ar':'en'}">${state.lang==='en'?'العربية':'English'}</button></div></div></header>`;}
function footer(){return `<footer class="site-footer"><span>${T('privacy')}</span><span class="footer-right">${T(storage.available?'saved':'memoryOnly')}<span class="dot"></span>${btn('print',T('print'))}</span></footer>`;}
function tierComparison(){return `<p class="notice">${T('baseline')}</p><div class="table-scroll"><table><thead><tr><th>${T('tier')}</th><th>${T('salary')}</th><th>${T('deposit')}</th><th>${T('dedicatedRm')}</th></tr></thead><tbody>${data.tiers.map(tier=>`<tr><th><span class="tier-dot ${tier.id}"></span>${E(tier.name)}</th><td>SAR ${tier.salary.toLocaleString('en-US')}+</td><td>SAR ${tier.deposit.toLocaleString('en-US')}+</td><td>${T(tier.rm?'yes':'no')}</td></tr>`).join('')}</tbody></table></div><p class="tiny">${T('qualificationNote')}</p>`;}
function selectField(id,label,choices,value,extra=''){return `<label for="${id}">${esc(label)}<select id="${id}" ${extra}>${choices.map(([v,k])=>`<option value="${v}" ${value===v?'selected':''}>${esc(T(k))}</option>`).join('')}</select></label>`;}
function currentProfile(){const tier=by('tiers',state.journey.tier);const p=by('personas',tier.personaId);return {...p,...(state.journey.profiles[state.journey.tier]||{})};}
function renderHome(){const p=currentProfile();return `<div class="home-wrap"><section class="opening"><span class="eyebrow"><span class="small-line"></span>${T('openingKicker')}</span><h1>${T('tagline')}</h1><p class="opening-subtitle">${T('subtitle')}</p><p class="opening-description">${T('openingBody')}</p></section><section aria-label="${T('choose')}" class="persona-grid">${data.tiers.map((tier,i)=>{const persona=by('personas',tier.personaId);return `<button class="persona-card ${tier.id} ${tier.id===state.journey.tier?'selected':''}" data-action="select-tier" data-tier="${tier.id}" aria-pressed="${tier.id===state.journey.tier}"><div class="persona-top"><span class="tier-label"><span class="tier-dot ${tier.id}"></span>${E(tier.name)}</span><span class="choice-mark">${state.journey.tier===tier.id?'✓':`0${i+1}`}</span></div><div class="persona-portrait">${person(tier.id)}</div><div class="persona-info"><h2>${E(persona.name)}<span>${persona.age} · ${E(persona.city)}</span></h2><p class="persona-role">${E(persona.role)}</p><p class="persona-bio">${E(persona.bio)}</p><div class="persona-model">${tier.rm?T('dedicatedRm'):T('support')}<span>→</span></div></div></button>`}).join('')}</section><div class="opening-actions">${btn('start',T('start')+' →','button primary large')}${btn('guided',T('guided'),'button secondary large')}${btn('explore-all',T('explore'),'text-button')}</div><p class="fiction-note">◇ ${T('fiction')}</p><details class="profile-options"><summary>${T('optional')}</summary><div class="form-grid">${selectField('profile-city',T('city'),[['riyadh','Riyadh'],['jeddah','Jeddah'],['dammam','Dammam']],p.cityCode|| (p.tier==='platinum'?'jeddah':'riyadh'),'data-profile="cityCode"')}${selectField('profile-gender',T('gender'),[['female','female'],['male','male']],p.gender,'data-profile="gender"')}${selectField('profile-digital',T('digitalConfidence'),[['high','high'],['medium','medium'],['low','low']],p.digital,'data-profile="digital"')}${selectField('profile-banking',T('banking'),[['primary','primary'],['multi','multi']],p.banking,'data-profile="banking"')}${selectField('profile-life',T('life'),[['professional','professional'],['travel','travel'],['family','familyContext'],['business','business']],p.life,'data-profile="life"')}${selectField('profile-start',T('situation'),[['new','new'],['unsure','unsure'],['upgraded','upgraded'],['urgent','urgent'],['switching','switching']],state.journey.starting,'data-profile="starting"')}</div><p class="tiny">${T('profileNote')}</p></details><details class="tier-comparison"><summary>${T('tierCompare')}</summary>${tierComparison()}</details><section class="home-route" aria-label="${T('journey')}"><svg viewBox="0 0 1000 120" aria-hidden="true"><path d="M50 80Q150 30 240 72T440 60T650 73T950 40" fill="none" stroke="#c2cab9" stroke-width="2" stroke-dasharray="6 7"/></svg>${data.chapters.map((ch,i)=>`<div><span class="chapter-letter">${ch.id}</span><p>${E(ch.title)}</p></div>`).join('')}</section><p class="research-link">${data.findings.length} ${T('findings').toLowerCase()} · ${T('interviews')} · ${T('painInventory')} ${btn('nav',T('evidence')+' →','text-button','data-view="evidence"')}</p></div>`;}
function renderJourney(){const j=state.journey;const tier=by('tiers',j.tier);const scene=by('scenes',j.stage);const route=data.routes[j.tier];const routeIndex=route.indexOf(j.stage);const p=currentProfile();return `<div class="journey-wrap ${state.presenter?'presentation':''}">${state.presenter?presentationBar(data,state.presenter,state.lang):''}<div class="journey-toolbar"><div class="current-persona"><span class="mini-avatar">${person(j.tier,true,p.gender)}</span><div><span class="eyebrow">${tierName(j.tier)} · ${E(p.name)}</span><h1>${state.lang==='en'?'Find the issue. Know what to check.':'حدّد المشكلة. واعرف وش نبحث عنه.'}</h1></div></div><div class="journey-tools"><label class="sr-only" for="tier-switch">${T('compare')}</label><select id="tier-switch" title="${T('compare')}">${data.tiers.map(t=>`<option value="${t.id}" ${t.id===j.tier?'selected':''}>${tierName(t.id)}</option>`).join('')}</select><label class="sr-only" for="experience-mode">${T('beforeAfter')}</label><select id="experience-mode"><option value="current" ${j.mode==='current'?'selected':''}>${T('current')}</option><option value="future" ${j.mode==='future'?'selected':''}>${T('future')}</option></select>${btn('share','→','icon-button',`aria-label="${T('share')}" title="${T('share')}"`)}${!state.presenter?btn('guided','▷','icon-button',`aria-label="${T('guided')}" title="${T('guided')}"`):''}</div></div>${j.mode==='future'?`<div class="proposal-banner" role="status">◇ ${T('proposal')}</div>`:''}<p class="scenario-emphasis"><span>${T('routeEmphasis')}</span> ${T(emphasis(p,j.starting))} ${p.cityCode==='jeddah'||p.cityCode==='dammam'?T('cityEmphasis'):''}</p><div class="journey-layout"><section class="map-column" aria-label="${T('map')}"><div class="map-topline"><span class="eyebrow">${T('journey')} ${routeIndex>=0?`· ${routeIndex+1} / ${route.length}`:''}</span>${btn('jump-scene',T('jumpScene'),'jump-scene')}<div class="view-toggle"><button data-action="map-view" aria-pressed="${!j.narrative}">${T('map')}</button><button data-action="narrative-view" aria-pressed="${j.narrative}">${T('narrative')}</button></div></div>${j.narrative?renderNarrative():renderMap()}<div class="map-caption"><span>${state.journey.result?.channel?esc(channelName(state.journey.result.channel))+' · ':''}● ${T('current')} <span class="outline-dot"></span> ${T('needed')}</span>${btn('channel-atlas',T('moreChannels')+' →')}</div><details class="supporting-details map-support"><summary>${state.lang==='ar'?'المنتجات وسجل الرحلة':'Products and journey history'}</summary><div class="context-products"><div><h2>${T('shelf')}</h2>${btn('products',T('products')+' →')}</div><div class="product-ribbon">${relevantProducts(j.stage,j.tier).slice(0,4).map(p=>`<button data-action="product" data-id="${p.id}"><span class="product-symbol">${p.id==='deposit'?'◉':p.id==='family'?'♧':p.id==='credit'||p.id==='debit'?'▱':'◇'}</span>${E(p.title)}<span>→</span></button>`).join('')}</div></div>${renderTrail()}</details></section><aside class="scene-panel" aria-labelledby="scene-heading">${renderScene(scene)}</aside></div><details class="supporting-details indicators-details"><summary>${state.lang==='ar'?'مؤشرات توضيحية إضافية':'Additional illustrative indicators'}</summary><section class="journey-indicators"><div><span class="eyebrow">${T('illustrativeIndicators')}</span><p>${T('indicatorNote')}</p></div><dl>${['recognition','effort','continuity','value','trust'].map(k=>`<div><dt>${T(k)}</dt><dd>${T(k==='effort'&&j.result?.repeat?'elevated':k==='trust'&&j.result?.id==='rm-call'?'supported':k==='effort'?'toValidate':'uncertain')}</dd></div>`).join('')}</dl></section></details></div>`;}
function relevantProducts(stage,tier){const ids=tier==='gold'?['debit','personal','auto']:tier==='platinum'?['lifestyle','credit','fx']:['deposit','invest','family'];return [...data.products.filter(p=>p.stageIds.includes(stage)),...data.products.filter(p=>ids.includes(p.id))].filter((p,i,arr)=>arr.findIndex(x=>x.id===p.id)===i);}
function renderMap(){const j=state.journey;const entry=state.journey.stage==='discover'&&state.journey.result?state.journey.result:state.journey.trail.find(e=>e.stage==='discover');const entryRaw=entry?entryPosition(entry.channel):null;const entryPoint=entryRaw?{...entryRaw,x:state.lang==='ar'?100-entryRaw.x:entryRaw.x}:null;const positions=data.stages.map(s=>({...s,x:state.lang==='ar'?100-s.x:s.x}));const curve=state.lang==='ar'?-65:65;const route=data.routes[j.tier];let path='';positions.forEach((n,i)=>{const px=n.x*10,py=n.y*6;if(i===0)path=`M${px} ${py}`;else{const prev=positions[i-1];path+=prev.y===n.y?` L${px} ${py}`:` C${prev.x*10+curve} ${prev.y*6+30} ${px+curve} ${py-30} ${px} ${py}`}});return `<div class="map-viewport" tabindex="0" aria-label="${T('map')}"><div class="journey-map" style="--zoom:${j.zoom}"><div class="map-paper"></div><svg class="map-routes" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true"><path d="${path}" class="base-route"/><path d="M130 114Q210 160 370 294M620 114Q580 225 130 294M860 294Q580 335 130 474" class="branch-route" ${state.lang==='ar'?'transform="translate(1000 0) scale(-1 1)"':''}/>${positions.map(n=>`<circle cx="${n.x*10}" cy="${n.y*6}" r="5" class="route-dot"/>`).join('')}</svg>${entryPoint?`<svg class="map-routes active-entry-route" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true"><path d="M${positions[0].x*10} ${positions[0].y*6} Q${entryPoint.x*10} ${positions[0].y*6+35} ${entryPoint.x*10} ${entryPoint.y*6}"/></svg><button class="entry-channel" style="left:${entryPoint.x}%;top:${entryPoint.y}%;" data-action="channel" data-id="${entry.channel}" aria-label="${T('selectedTouchpoint')}: ${esc(channelName(entry.channel))}"><span>${entry.channel==='website'?'▤':entry.channel==='branch'?'⌂':entry.channel==='rm'?'◉':entry.channel==='phone'?'◌':'▯'}</span>${esc(channelName(entry.channel))}</button>`:''}<span class="map-note note-a">${state.lang==='ar'?'كل بداية تكشف شيئًا':'Every entry tells a story'}</span><span class="map-note note-b">${state.lang==='ar'?'أسئلة تستحق المتابعة':'Follow the open questions'}</span>${positions.map((n,i)=>`<button class="map-node ${route.includes(n.id)?'on-route':''} ${n.id===j.stage?'is-current':''} ${j.explored.includes(j.tier+':'+n.id)?'explored':''}" style="left:${n.x}%;top:${n.y}%;--tier-color:${by('tiers',j.tier).color}" data-action="stage" data-stage="${n.id}" ${n.id===j.stage?'aria-current="step"':''} aria-label="${i+1}. ${E(n.title)}"><span class="node-art">${art(n.art,j.tier)}</span><span class="node-label"><span class="node-index">${String(i+1).padStart(2,'0')}</span>${E(n.title)}</span>${j.explored.includes(j.tier+':'+n.id)?'<span class="stamp-check">✓</span>':''}</button>`).join('')}<span class="customer-avatar ${j.tier}" aria-hidden="true">${person(j.tier,true,currentProfile().gender)}</span><button class="gap-node gap-one" data-action="gap" data-id="G14" aria-label="${T('gaps')}: ${E(by('gaps','G14').title)}"><span>◇</span>${state.lang==='ar'?'قواعد التأهل؟':'Which rules?'}</button><button class="gap-node gap-two" data-action="gap" data-id="G11" aria-label="${T('gaps')}: ${E(by('gaps','G11').title)}"><span>◇</span>${state.lang==='ar'?'من يعالج؟':'Who resolves?'}</button></div><div class="map-zoom"><button data-action="zoom-out" ${j.zoom<=1?'disabled':''} aria-label="${T('zoomOut')}">−</button><button data-action="zoom-reset" aria-label="${T('resetZoom')}">${Math.round(j.zoom*100)}%</button><button data-action="zoom-in" ${j.zoom>=1.5?'disabled':''} aria-label="${T('zoomIn')}">+</button></div></div>`;}
function renderNarrative(){return `<ol class="narrative-route">${data.stages.map(s=>`<li class="${s.id===state.journey.stage?'is-current':''}"><span class="chapter-letter">${s.chapter}</span><div><button data-action="stage" data-stage="${s.id}" ${s.id===state.journey.stage?'aria-current="step"':''}>${E(s.title)}</button><p>${E(by('scenes',s.id).goal)}</p></div><button class="gap-mini" data-action="scene-gaps" data-stage="${s.id}" aria-label="${T('missing')}: ${E(s.title)}">◇</button></li>`).join('')}</ol>`;}
function renderTrail(){const trail=state.journey.trail;return `<section class="journey-trail" id="journey-trail" tabindex="-1"><div class="section-line"><h2>${T('passport')}</h2><span>${new Set(trail.map(e=>e.tier+':'+e.stage)).size} ${T('stamps')}</span></div><p class="tiny">${T('trail')}</p>${trail.length?`<ol>${trail.map((entry,i)=>`<li><span class="trail-stamp">${i+1}</span><div><button data-action="revisit" data-index="${i}">${esc(stageName(entry.stage))} · ${esc(tierName(entry.tier))}</button><p>${esc(channelName(entry.channel))}${entry.nextChannel!==entry.channel?' → '+esc(channelName(entry.nextChannel)):''} ${entry.proposal?badge(T('proposed'),'outlined'):''}</p><small>${T(entry.repeat?'repeat':'carried')}</small></div></li>`).join('')}</ol>`:`<p class="empty-trail">${T('noTrail')}</p>`}</section>`;}
function renderSimulation(scene,result){const defaults={discover:state.journey.tier==='elite'?'branch':'app',qualify:['app','website','branch'].includes(state.journey.channel)?state.journey.channel:'branch',welcome:'message',daily:'branch',relationship:state.journey.tier==='gold'?'phone':'rm',value:state.journey.tier==='elite'?'rm':'app',privileges:'partner',resolve:'phone',family:'family',grow:state.journey.tier==='gold'?'website':'rm',lifecycle:'message'};const active=result?.channel||defaults[scene.id]||'app';const resolved=!!result;const subtitle=resolved?T('response'):T('previewOnly');let body='';
 if(active==='app'||active==='message')body=`<div class="sim-device"><div class="sim-device-bar"><span>9:41</span><span>••• ▰</span></div><div class="sim-app-heading">Wessam<span class="tier-dot ${state.journey.tier}"></span></div><div class="sim-tier-card ${state.journey.tier}"><small>${tierName(state.journey.tier)}</small><strong>${esc(stageName(scene.id))}</strong><span>${T(resolved?'toValidate':'previewOnly')}</span></div><div class="sim-app-row"><span>◇</span>${T('benefits')}<i>›</i></div><div class="sim-app-row"><span>⌁</span>${T(state.journey.tier==='gold'?'support':'dedicatedRm')}<i>›</i></div>${btn('products',T('shelf'),'sim-link')}</div>`;
 else if(active==='website')body=`<div class="sim-browser"><div class="browser-bar"><i></i><i></i><i></i><span>${T('previewOnly')}</span></div><div class="browser-page"><span class="eyebrow">Wessam</span><h3>${T('tierCompare')}</h3><div class="mini-tiers">${data.tiers.map(t=>`<span class="${t.id}">${E(t.name)}</span>`).join('')}</div><div class="skeleton-line"></div><div class="skeleton-line short"></div>${btn('tier-comparison',T('tierCompare')+' →','sim-link')}</div></div>`;
 else if(active==='phone'||active==='rm'||active==='whatsapp')body=`<div class="sim-call"><span class="call-avatar">${art(active==='phone'?'call':'rm',state.journey.tier)}</span><h3>${esc(channelName(active))}</h3><p>${T(active==='phone'?'context':'dedicatedRm')} · ${T('unverified')}</p><div class="call-controls"><span>◌</span><span>⌨</span><span>→</span></div>${btn('trail',T('trail')+' →','sim-link')}</div>`;
 else if(active==='branch'||active==='wessam-area'||active==='kiosk')body=`<div class="sim-branch">${art('branch',state.journey.tier)}<div class="branch-tags">${badge(T('recognition'),'outlined')}${badge(T('toValidate'))}</div>${btn('branch-channel',T('services')+' →','sim-link')}</div>`;
 else if(active==='partner')body=`<div class="sim-partner">${art('airport',state.journey.tier)}<div>${badge(T(state.journey.tier==='gold'?'card':'unknown'),'outlined')}</div>${btn('benefit-checklist',T('questionnaire')+' →','sim-link')}</div>`;
 else if(active==='family')body=`<div class="sim-branch">${art('family',state.journey.tier)}<p class="tiny">${T('toValidate')}</p>${btn('gap',T('remaining')+' →','sim-link','data-id="G13"')}</div>`;
 else body=`<div class="sim-browser"><div class="browser-bar">X · ${T('previewOnly')}</div><div class="browser-page"><span class="eyebrow">${T('hypothesis')}</span><h3>${T('ownerConfirmed')}</h3><p>${T('unverified')}</p>${btn('channel','X / Twitter →','sim-link','data-id="x"')}</div></div>`;
 return `<div class="interaction-simulation ${resolved?'responded':''}" aria-label="${T('simulated')}"><span class="simulation-label">${subtitle}</span>${body}</div>`;
}
function renderResearchFocus(scene){const gaps=scene.gapIds.map(id=>by('gaps',id)).filter(g=>g&&g.tierScope.includes(state.journey.tier));return `<section class="research-focus" aria-label="${state.lang==='ar'?'محور البحث':'Research focus'}"><div class="focus-problem"><span class="focus-label">${state.lang==='ar'?'وش المشكلة أو الشيء غير المحسوم؟':'The issue or uncertainty'}</span><p>${E(scene.reveal)}</p><small>${state.lang==='ar'?'ملاحظات مروية وأسئلة للتحقق؛ لا تعني إخفاقًا مؤكدًا.':'Reported observations and open questions; not confirmed failures.'}</small></div><div class="focus-questions"><h3>${state.lang==='ar'?'وش نحتاج نتحقق منه؟':'What do we need to check?'}</h3>${gaps.length?`<ol>${gaps.map(g=>`<li><p>${E(g.question)}</p><details><summary>${state.lang==='ar'?'الدليل المطلوب والمسؤول':'Evidence needed and owner'}</summary><p>${E(g.requiredEvidence)}</p><small>${esc(ownerName(g.owner))}</small>${btn('gap',T('details')+' →','text-button',`data-id="${g.id}"`)}</details></li>`).join('')}</ol>`:`<p>${E(scene.expected)}</p>`}</div></section>`;}
function renderScene(scene){const j=state.journey;if(scene.id==='debrief')return renderDebrief();const result=j.result;const actions=getActions(data,j.tier,j.stage);const findings=sceneFindings(j.stage);const p=currentProfile();return `<div class="scene-heading"><span class="eyebrow">${by('stages',j.stage).chapter} · ${E(data.chapters.find(c=>c.id===by('stages',j.stage).chapter).title)}</span><h2 id="scene-heading" tabindex="-1">${E(scene.goal)}</h2><p>${E(scene.situation)}</p></div>${renderResearchFocus(scene)}<details class="supporting-details simulation-details"><summary>${state.lang==='ar'?'عرض محاكاة القناة':'View channel illustration'}</summary><p class="simulation-note">${T('simulated')}</p>${renderSimulation(scene,result)}</details>${j.tier==='gold'&&j.stage==='relationship'?`<p class="notice">${T('goldNoRm')}</p>`:''}${!result?`<fieldset class="action-choices" ${state.presenter?.paused?'disabled':''}><legend>${T('actions')}</legend>${actions.map((a,i)=>`<button data-action="choose" data-id="${a.id}"><span>${String(i+1).padStart(2,'0')}</span><div>${E(a.title)}<small>${esc(channelName(a.channel))}</small></div><span>→</span></button>`).join('')}</fieldset>`:`<div class="scene-result" role="status" tabindex="-1"><div class="response-heading">${badge(B(result.kind==='unknown'?'missing':result.kind==='illustrative'?'illustrative':'reported'),'outlined')}<span>${esc(channelName(result.channel))}${result.nextChannel!==result.channel?' → '+esc(channelName(result.nextChannel)):''}</span></div><p>${E(result.response)}</p>${j.mode==='future'?renderComparison(j.stage):''}${result.repeat?`<p class="context-caution">${T('repeat')}</p>`:''}</div>`}<div class="scene-detail-buttons">${btn('scene-evidence',T('viewEvidence')+` (${findings.length})`)}${btn('scene-gaps',T('missing')+' ◇','text-button',`data-stage="${j.stage}"`)}${btn('scene-owner',T('whoOwns')+' →')}</div>${j.stage==='resolve'?btn('attribution',T('attribution')+' →','attribution-link'):''}<div class="scene-navigation">${btn('back',T('back'),'button secondary',!j.trail.length&&!result?'disabled':'')}${result?btn('continue',T('continue')+' →','button primary',state.presenter?.paused?'disabled':''):''}</div>${result?btn('try-again',T('tryAgain'),'try-again'):''}<div class="scene-tier-compare"><span>${T('compare')}</span><div>${data.tiers.map(tier=>`<button data-action="compare-tier" data-tier="${tier.id}" aria-pressed="${tier.id===j.tier}"><span class="tier-dot ${tier.id}"></span>${E(tier.name)}</button>`).join('')}</div></div>`;}
function renderDebrief(){const j=state.journey;return `<div class="debrief-illustration">${art('passport',j.tier)}</div><span class="eyebrow">${T('passport')}</span><h2 id="scene-heading" tabindex="-1">${T('debrief')}</h2><p>${T('debriefBody')}</p><dl class="debrief-stats"><div><dt>${T('stamps')}</dt><dd>${j.explored.length}</dd></div><div><dt>${T('questionsReviewed')}</dt><dd>${j.reviewed.length}</dd></div></dl><fieldset class="ending-choices"><legend>${T('ending')}</legend>${['stay','deepen','help','move'].map(key=>`<button data-action="ending" data-ending="${key}" aria-pressed="${j.ending===key}">${j.ending===key?'✓':'○'} ${T(key)}</button>`).join('')}</fieldset><p class="tiny">${T('endingNote')}</p><p class="notice">${T('auditNote')}</p><div class="scene-detail-buttons">${btn('scene-evidence',T('viewEvidence'))}${btn('scene-gaps',T('missing'),'text-button','data-stage="debrief"')}</div>${btn('nav',T('reviewDecisions')+' →','button primary','data-view="governance"')}${btn('start',T('restart'),'text-button')}${btn('back',T('back'),'text-button')}</div>`;}
function renderComparison(stage){const concepts=data.concepts.filter(c=>c.stageId===stage||stage==='qualify'&&c.stageId==='welcome'||stage==='value'&&c.stageId==='grow');return `<div class="comparison-box"><span class="eyebrow">${T('proposal')}</span><h3>${T('beforeAfter')}</h3><p><strong>${T('reportedBefore')}</strong> ${E(by('scenes',stage).reveal)}</p>${concepts.length?concepts.map(c=>`<div><strong>${T('proposedAfter')}: ${E(c.title)}</strong><p>${T('need')}: ${E(c.need)}</p><p>${T('owner')}: ${esc(ownerName(c.owner))}</p><p>${T('dependencies')}: ${E(by('dependencies',c.dependency)?.title||c.dependency)}</p><p>${T('feasibility')}: ${E(c.feasibility)}</p><p>${T('measures')}: ${E(c.measure)} · ${T('baselineLabel')}: ${T('dataRequired')} · ${T('target')}: ${T('dataRequired')}</p></div>`).join(''):`<p>${T('noConcept')}</p>`}</div>`;}
function sceneFindings(stage,tier=state.journey.tier){let records=data.findings.filter(f=>f.stageIds.includes(stage)&&f.tierScope.includes(tier));const channel=state.journey.result?.channel;if(stage==='discover'&&channel)records=records.filter(f=>f.touchpointIds.includes(channel));return records;}
function inventoryStrip(){return `<div class="inventory-strip"><div><strong>${data.findings.length}</strong><span>${T('findings')}</span></div><div><strong>${data.meta.reportedInterviews}</strong><span>${T('interviews').replace(/^12 |^١٢ /,'')}</span></div><div><strong>${data.meta.reportedPainEntries}</strong><span>${T('painInventory').replace(/^170 |^١٧٠ /,'')}</span></div><p>${T('auditNote')}</p></div>`;}
function filterSelect(field,label,options){return `<label>${esc(label)}<select id="filter-${field}" data-filter="${field}"><option value="">${T('all')}</option>${options.map(([v,label])=>`<option value="${esc(v)}" ${state.filter[field]===v?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;}
function findingRow(f){return `<article class="finding-row"><div class="finding-signal ${f.positiveOrPain}" aria-hidden="true">${f.positiveOrPain==='positive'?'+':f.positiveOrPain==='pain'?'!':'◇'}</div><div class="finding-content"><div class="record-meta"><span>${f.id}</span><span>${esc(f.sourcePeriod)}</span>${statusBadge(f.validationStatus)}${badge(f.evidenceType==='historical'?T('historicalStudy'):B(f.evidenceType))}</div><h3><button data-action="finding" data-id="${f.id}">${E(f.title)}</button></h3><p>${E(f.summary)}</p><small>${esc(f.tierScope.map(tierName).join(' · '))} · ${E(by('evidence',f.sourceId).title)}</small></div><button data-action="finding" data-id="${f.id}" class="row-arrow" aria-label="${T('details')}: ${E(f.title)}">→</button></article>`;}
function filteredFindings(){return data.findings.filter(f=>{const a=state.filter;const source=by('evidence',f.sourceId);return(!a.tier||f.tierScope.includes(a.tier))&&(!a.stage||f.stageIds.includes(a.stage))&&(!a.channel||f.touchpointIds.includes(a.channel))&&(!a.validation||f.validationStatus===a.validation)&&(!a.type||f.evidenceType===a.type)&&(!a.source||f.sourceId===a.source)&&(!a.period||f.sourcePeriod===a.period)&&(!a.method||f.sourceId===a.method)&&(!a.polarity||f.positiveOrPain===a.polarity)&&(!a.search||(JSON.stringify(f.title)+' '+JSON.stringify(f.summary)).toLowerCase().includes(a.search.toLowerCase()))});}
function renderEvidence(){const records=filteredFindings();return `<div class="content-wrap"><div class="page-heading"><div><span class="eyebrow">${T('evidence')}</span><h1>${state.lang==='ar'?'رؤى لها أصل، وأسئلة لها مكان.':'Every insight has a source.'}</h1><p>${T('loadedNote')}</p></div><div class="page-actions">${btn('positive-filter',T('positiveEvidence'),'button secondary')}${btn('export-csv',T('exportCsv'),'text-button','data-collection="findings"')}</div></div>${inventoryStrip()}<div class="evidence-tabs"><button data-action="findings-tab" aria-pressed="${!state.sourceTab}">${T('findings')} (${data.findings.length})</button><button data-action="sources-tab" aria-pressed="${state.sourceTab}">${T('sources')} (${data.evidence.length})</button></div>${!state.sourceTab?`<div class="filter-bar"><label class="search-label">${T('search')}<input id="record-search" type="search" value="${esc(state.filter.search||'')}" placeholder="${T('search')}"></label>${filterSelect('tier',T('tier'),data.tiers.map(t=>[t.id,L(t.name)]))}${filterSelect('stage',T('scene'),data.stages.map(s=>[s.id,L(s.title)]))}${filterSelect('channel',T('channels'),data.touchpoints.map(x=>[x.id,L(x.title)]))}${filterSelect('validation',T('validation'),['reported','validated','historical','hypothesis','missing'].map(x=>[x,B(x)]))}<details class="more-filters"><summary>${T('filter')} +</summary><div>${filterSelect('source',T('source'),data.evidence.map(s=>[s.id,L(s.title)]))}${filterSelect('period',T('period'),[...new Set(data.findings.map(f=>f.sourcePeriod))].map(x=>[x,x]))}${filterSelect('type',T('evidenceType'),['customer','staff','observation','historical','cx','operational','illustrative'].map(x=>[x,B(x)]))}${filterSelect('method',T('method'),data.evidence.map(s=>[s.id,L(s.method)]))}</div></details>${btn('clear-filters',T('clearFilters'))}</div><p class="tiny result-count">${records.length} ${T('recordCount')} · ${T('findingCount')}</p><div class="findings-list">${records.length?records.map(findingRow).join(''):`<p class="empty">${T('noResults')}</p>`}</div>`:`<div class="source-list">${data.evidence.map(s=>`<article class="source-record"><div class="record-meta"><span>${s.id}</span><span>${esc(s.period)}</span>${statusBadge(s.validationStatus)}</div><h2><button data-action="source" data-id="${s.id}">${E(s.title)}</button></h2><p>${E(s.method)}</p><p>${E(s.scope)}</p><p class="tiny">${T('lineage')}: ${esc(s.lineage)} · ${E(s.access)}</p>${btn('source',T('details')+' →','text-button',`data-id="${s.id}"`)}</article>`).join('')}</div>`}<p class="notice">${T('noPrivate')}</p></div>`;}
function renderGaps(){return `<div class="content-wrap"><div class="page-heading"><div><span class="eyebrow">${T('gaps')} · ${data.gaps.length}</span><h1>${state.lang==='ar'?'وش نحتاج نبحث عنه؟':'What do we need to investigate?'}</h1><p>${T('manualStatus')}</p></div>${btn('export-csv',T('exportCsv'),'button secondary','data-collection="gaps"')}</div><p class="tiny">${T('priorityNote')}</p><div class="gap-register">${data.gaps.map(g=>`<article class="gap-row"><span class="gap-diamond">◇</span><div><div class="record-meta"><span>${g.id}</span>${badge(T(g.priority),g.priority==='high'?'amber':'neutral')}${statusBadge(g.status)}</div><h2><button data-action="gap" data-id="${g.id}">${E(g.title)}</button></h2><p class="gap-question">${E(g.question)}</p><details class="supporting-details"><summary>${state.lang==='ar'?'وش الدليل المطلوب؟':'What evidence is needed?'}</summary><p>${E(g.requiredEvidence)}</p><p>${E(g.method)}</p></details><div class="gap-bottom"><span>${esc(ownerName(g.owner))}</span><span>${T('spoc')}: ${esc(g.spoc||T('unassigned'))}</span><span>${T('dueDate')}: ${esc(g.dueDate||T('tbd'))}</span></div></div><div class="gap-row-actions">${btn('gap',T('details')+' →','text-button',`data-id="${g.id}"`)}${btn('edit-record',T('edit'),'text-button',`data-collection="gaps" data-id="${g.id}"`)}</div></article>`).join('')}</div></div>`;}
function renderPlan(){return `<div class="content-wrap"><div class="page-heading"><div><span class="eyebrow">${T('plan')} · ${T('proposed')}</span><h1>${T('planKicker')}</h1><p>${T('recruitmentNote')}</p></div>${btn('nav',T('gaps')+' →','button secondary','data-view="gaps"')}</div><section class="plan-methods"><h2>${T('proposedMethods')}</h2><div>${data.plan.methods.map(m=>`<article><span class="method-bullet">◇</span><h3>${E(m.title)}</h3><p>${E(m.duration)}</p></article>`).join('')}</div></section><section class="phases-section"><h2>${T('phaseGates')}</h2><p class="tiny">${T('datesNote')}</p><ol class="phase-gates">${data.plan.phases.map((phase,i)=>`<li><span class="phase-number">${i+1}</span><div><strong>${E(phase.title)}</strong><small>${esc(phase.date||T('tbd'))} · ${B(phase.status)}</small></div>${btn('edit-phase','→','icon-button',`data-id="${phase.id}" aria-label="${T('edit')}: ${E(phase.title)}"`)}</li>`).join('')}</ol></section><section class="profile-section"><div class="section-line"><h2>${T('proposedProfiles')}</h2><span>${data.researchProfiles.length} ${T('recordCount')}</span></div><div class="profiles-grid">${data.tiers.map(tier=>`<section class="profile-tier ${tier.id}"><h3><span class="tier-dot ${tier.id}"></span>${E(tier.name)}</h3><ul>${data.researchProfiles.filter(p=>p.tier===tier.id).map(p=>`<li><span>${p.id}</span><div><strong>${E(p.city)}</strong><p>${E(p.context)}</p><small>${B(p.status)}</small></div></li>`).join('')}</ul></section>`).join('')}</div></section><section class="research-notes"><div><h2>${T('themes')}</h2><p>${E(data.plan.themes)}</p><h2>${T('outputs')}</h2><p>${E(data.plan.outputs)}</p></div><div><h2>${T('benchmarks')}</h2><p>${data.plan.benchmarks.map(esc).join(' · ')}</p><p class="tiny">${E(by('gaps','G09').missing)}</p>${btn('gap',T('details')+' →','text-button','data-id="G09"')}</div></section></div>`;}
function renderGovernance(){return `<div class="content-wrap"><div class="page-heading"><div><span class="eyebrow">${T('governance')}</span><h1>${T('leadership')}</h1><p>${T('governanceNote')}</p></div>${btn('export-csv',T('exportCsv'),'button secondary','data-collection="decisions"')}</div><section><h2>${T('decisionLog')}</h2><div class="decision-log">${data.decisions.map((d,i)=>`<article><span class="decision-number">0${i+1}</span><div><h3>${E(d.title)}</h3><p>${esc(d.decision||T('tbd'))}</p><small>${esc(ownerName(d.owner))} · ${B(d.status)} · ${esc(d.decisionDate||T('tbd'))}</small></div>${btn('edit-record',T('edit')+' →','text-button',`data-collection="decisions" data-id="${d.id}"`)}</article>`).join('')}</div></section><section class="governance-section"><h2>${T('spocTable')}</h2><div class="table-scroll"><table class="owners-table"><thead><tr><th>${T('owner')}</th><th>${T('contribution')}</th><th>${T('spoc')}</th><th>${T('status')}</th><th>${T('edit')}</th></tr></thead><tbody>${data.owners.map(o=>`<tr><th>${E(o.name)}</th><td>${E(o.contribution)}</td><td>${esc(o.spoc||T('unassigned'))}</td><td>${T(o.accepted?'accepted':'proposed')}</td><td>${btn('edit-record','→','icon-button',`data-collection="owners" data-id="${o.id}" aria-label="${T('edit')}: ${E(o.name)}"`)}</td></tr>`).join('')}</tbody></table></div></section><section class="governance-section"><h2>${T('dependencyRegister')}</h2><div class="dependencies-list">${data.dependencies.map(d=>`<article><span>${d.id}</span><div><h3>${E(d.title)}</h3><p>${esc(ownerName(d.owner))} · ${B(d.status)} · ${esc(d.dueDate||T('tbd'))}</p></div>${btn('edit-record',T('edit')+' →','text-button',`data-collection="dependencies" data-id="${d.id}"`)}</article>`).join('')}</div></section><section class="measure-panel"><h2>${T('successMeasures')}</h2><p>${T('measureList')}</p><dl><div><dt>${T('baselineLabel')}</dt><dd>${T('dataRequired')}</dd></div><div><dt>${T('target')}</dt><dd>${T('dataRequired')}</dd></div></dl></section></div>`;}
function collectionLabel(key){const mapping={findings:'findings',gaps:'gaps',evidence:'sources',products:'products',benefits:'benefits',touchpoints:'moreChannels',owners:'spocTable',decisions:'decisionLog',dependencies:'dependencyRegister',researchProfiles:'proposedProfiles',concepts:'concept',scenes:'scene',tiers:'tier',personas:'home',chapters:'journey',stages:'sceneNavigation',kickoff:'guided'};return T(mapping[key]||key);}
function renderEditor(){const col=state.editorCollection;return `<div class="content-wrap editor-wrap"><div class="page-heading"><div><span class="eyebrow">${T('editor')}</span><h1>${T('editorTitle')}</h1><p>${T('localNote')}</p></div>${statusBadge(storage.available?'available':'unknown')}</div><div class="editor-transfer"><div><h2>JSON</h2>${btn('export-json',T('exportJson'),'button primary')}<label class="button secondary file-label">${T('importJson')}<input id="import-file" class="sr-only" type="file" accept="application/json,.json"></label><p class="tiny">${T('schemaHelp')}</p></div><div><h2>CSV</h2><div class="csv-buttons">${['findings','gaps','products','decisions'].map(key=>btn('export-csv',collectionLabel(key),'button secondary',`data-collection="${key}"`)).join('')}</div></div></div><section class="editor-records"><div class="editor-record-toolbar"><label for="editor-collection">${T('collection')}<select id="editor-collection">${collections.map(c=>`<option value="${c}" ${c===col?'selected':''}>${collectionLabel(c)}</option>`).join('')}</select></label>${btn('add-record',T('addRecord')+' +','button primary',`data-collection="${col}"`)}</div><div class="editor-record-list">${data[col].map(r=>`<button data-action="edit-record" data-collection="${col}" data-id="${r.id}"><span>${r.id}</span><strong>${E(r.title||r.name||r.context||r.goal||r.id)}</strong><span>→</span></button>`).join('')}</div></section><div class="reset-section"><p>${T('noPrivate')}</p>${btn('reset-data',T('reset'),'text-button danger')}</div></div>`;}
function openDialog(title,html,context=null){returnFocus=document.activeElement;dialogContext=context;document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.querySelector('#dialog-close').focus();}
function closeDialog(){if(dialog.open)dialog.close();dialogContext=null;if(returnFocus?.isConnected)returnFocus.focus();else document.querySelector('#main')?.focus({preventScroll:true});}
function metaDL(rows){return `<dl class="detail-dl">${rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${value}</dd></div>`).join('')}</dl>`;}
function linkedGaps(ids){return `<div class="linked-records">${ids.map(id=>{const gap=by('gaps',id);return gap?btn('gap',`◇ ${id} · ${L(gap.title)}`,'gap-link',`data-id="${id}"`):''}).join('')}</div>`;}
function linkedSources(ids){return ids.map(id=>{const s=by('evidence',id);return s?btn('source',`${id} · ${L(s.title)} · ${s.period}`,'source-link',`data-id="${id}"`):''}).join('');}
function measureBlock(measures){return `<section class="detail-section"><h3>${T('measures')}</h3><p>${esc(measures||T('measureList'))}</p>${metaDL([[T('baselineLabel'),T('dataRequired')],[T('target'),T('dataRequired')]])}</section>`;}
function markReviewed(id){if(!state.journey.reviewed.includes(id))state.journey.reviewed.push(id);persist();}
function showFinding(id){const f=by('findings',id);if(!f)return;markReviewed(id);const source=by('evidence',f.sourceId);const positives=data.findings.filter(x=>x.id!==f.id&&x.positiveOrPain==='positive'&&x.stageIds.some(s=>f.stageIds.includes(s))&&x.tierScope.some(t=>f.tierScope.includes(t)));openDialog(L(f.title),`<div class="detail-badges">${badge(f.id)}${statusBadge(f.validationStatus)}${badge(f.evidenceType==='historical'?T('historicalStudy'):B(f.evidenceType))}${badge(B(f.positiveOrPain),f.positiveOrPain==='positive'?'green':'neutral')}</div><p class="detail-lead">${E(f.summary)}</p>${metaDL([[T('yourGoal'),E(by('scenes',f.stageIds[0])?.goal)],[T('expected'),E(f.expectedExperience)],[T('symptom'),E(f.summary)],[T('scope'),esc(f.tierScope.map(tierName).join(' · '))+' / '+esc(f.stageIds.map(stageName).join(' · '))],[T('channels'),esc(f.touchpointIds.map(channelName).join(' · '))],[T('source'),linkedSources([f.sourceId])],[T('period'),esc(f.sourcePeriod)],[T('method'),E(source.method)],[T('lineage'),esc(f.sourceLineageId)],[T('capability'),B(f.capabilityStatus)],[T('completeness'),f.researchCompleteness==='partial'?T('researchPartial'):B(f.researchCompleteness)],[T('lifecycle'),B(f.lifecycle)]])}<p class="notice">${E(source.access)}</p>${positives.length?`<section class="detail-section"><h3>${T('positiveEvidence')}</h3>${positives.map(x=>btn('finding',L(x.title)+' →','source-link',`data-id="${x.id}"`)).join('')}</section>`:''}<section class="detail-section"><h3>${T('pain')}</h3>${data.findings.filter(x=>x.id!==f.id&&x.positiveOrPain==='pain'&&x.stageIds.some(s=>f.stageIds.includes(s))&&x.tierScope.some(t=>f.tierScope.includes(t))).slice(0,4).map(x=>btn('finding',L(x.title)+' →','source-link',`data-id="${x.id}"`)).join('')||`<p>${T('dataRequired')}</p>`}</section><section class="detail-section"><h3>${T('hypothesisLabel')}</h3>${badge(T('hypothesis'),'outlined')}<p>${E(f.rootCauseHypothesis)}</p></section><section class="detail-section"><h3>${T('remaining')}</h3>${linkedGaps(f.linkedGapIds)}</section>${metaDL([[T('owner'),esc(ownerName(f.proposedOwner))+' · '+T('proposedOwner')],[T('nextValidation'),E(f.nextValidationAction)],[T('severity'),f.severity==null?T('unassessed'):esc(f.severity)],[T('frequency'),f.frequency==null?T('unassessed'):esc(f.frequency)]])}<section class="detail-section"><h3>${T('concept')}</h3>${renderComparison(f.stageIds[0])}</section>${measureBlock()}<div class="detail-actions">${btn('edit-record',T('edit'),'button secondary',`data-collection="findings" data-id="${f.id}"`)}</div>`);}
function showSource(id){const s=by('evidence',id);if(!s)return;markReviewed(id);openDialog(L(s.title),`<div class="detail-badges">${badge(s.id)}${statusBadge(s.validationStatus)}</div>${metaDL([[T('period'),esc(s.period)],[T('method'),E(s.method)],[T('scope'),E(s.scope)],[T('lineage'),esc(s.lineage)],[T('linkedEvidence'),esc(s.reference||T('dataRequired'))]])}<p class="notice">${E(s.access)}</p><p>${T('loadedNote')}</p>${s.id==='S09'?`<p>${state.lang==='ar'?'ثمانية محاور تاريخية: التخصيص والظهور والكفاءة والتكامل والأدوات المالية والثقة والأمان والتفاعل الاستباقي والتصميم المتمحور حول المستخدم. ليست نتائج المصرفية الخاصة.':'Eight historical themes: personalization, visibility, efficiency, integration, financial tools, trust/security, proactive engagement and user-centered design. Private Banking is excluded.'}</p>`:''}${s.id==='S08'?`<p>${state.lang==='ar'?'لا تطابق مجموعات الأفلونت الدنيا والعليا مباشرة مع شرائح وسام الحالية.':'Do not map Lower / Upper Affluent directly onto current Wessam tiers.'}</p>`:''}<div class="linked-records">${data.findings.filter(f=>f.sourceId===id).map(f=>btn('finding',f.id+' · '+L(f.title),'source-link',`data-id="${f.id}"`)).join('')}</div>${btn('edit-record',T('edit'),'button secondary',`data-collection="evidence" data-id="${id}"`)}`);}
function showGap(id){const g=by('gaps',id);if(!g)return;markReviewed(id);openDialog(L(g.title),`<div class="detail-badges">${badge(g.id,'outlined')}${statusBadge(g.status)}${badge(T(g.priority),'amber')}</div><p class="detail-lead">${E(g.question)}</p>${metaDL([[T('scope'),esc(g.tierScope.map(tierName).join(' · '))],[T('scene'),esc(g.stageIds.map(stageName).join(' · '))],[T('channels'),esc(g.touchpointIds.map(channelName).join(' · '))],[T('products'),g.productIds.length?esc(g.productIds.map(id=>L(by('products',id).title)).join(' · ')):T('toValidate')],[T('themes'),esc(B(g.theme))],[T('have'),E(g.have)],[T('remaining'),E(g.missing)],[T('why'),E(g.why)],[T('requiredEvidence'),E(g.requiredEvidence)],[T('method'),E(g.method)],[T('owner'),esc(ownerName(g.owner))+' · '+T('proposedOwner')],[T('spoc'),esc(g.spoc||T('unassigned'))],[T('priority'),T(g.priority)+' · '+E(g.priorityBasis)],[T('requestStatus'),B(g.requestStatus)],[T('dueDate'),esc(g.dueDate||T('tbd'))],[T('dependencies'),esc(g.dependencies.map(id=>L(by('dependencies',id).title)).join(' · '))],[T('validator'),esc(g.validator||T('unassigned'))],[T('validatedAt'),esc(g.validatedAt||T('tbd'))],[T('notes'),esc(g.notes||T('dataRequired'))]])}<section class="detail-section"><h3>${T('linkedEvidence')}</h3>${linkedSources(g.evidenceIds)}</section><p class="notice">${T('manualStatus')}</p><div class="detail-actions">${btn('edit-record',T('edit'),'button primary',`data-collection="gaps" data-id="${g.id}"`)}${btn('add-evidence',T('addEvidence'),'button secondary',`data-gap="${id}"`)}${btn('goto-scene',T('openScene')+' →','text-button',`data-stage="${g.stageIds[0]}"`)}</div>`);}
function showSceneGaps(stage){const s=by('scenes',stage);openDialog(T('missing')+' · '+stageName(stage),`<p class="notice">${T('unknown')} ≠ ${T('unavailable')}</p>${linkedGaps(s.gapIds)}<p>${T('manualStatus')}</p>${btn('add-evidence',T('addEvidence'),'button secondary',`data-gap="${s.gapIds[0]}"`)}`);}
function showSceneEvidence(){const records=sceneFindings(state.journey.stage);openDialog(T('viewEvidence')+' · '+stageName(state.journey.stage),`<p class="tiny">${T('loadedNote')}</p><div class="findings-list">${records.map(findingRow).join('')||`<p>${T('dataRequired')}</p>`}</div>${linkedGaps(by('scenes',state.journey.stage).gapIds)}`);}
function showProduct(id){const p=by('products',id);if(!p)return;const related=data.findings.filter(f=>f.productIds.includes(id));openDialog(L(p.title),`<div class="product-detail-hero">${art(id==='lifestyle'?'airport':id==='family'?'family':'value',state.journey.tier)}<div>${badge(B(p.valueLabel),'outlined')}${statusBadge(p.validationStatus)}<p>${E(p.need)}</p><small>${E(by('tiers',state.journey.tier).focus)}</small></div></div><p class="notice">${T('valueWarning')}</p>${metaDL([[T('need'),E(p.need)],[T('availability'),data.tiers.map(tier=>`${tierName(tier.id)}: ${B(p.availability[tier.id])}`).join('<br>')],[T('channels'),esc(p.channels.filter(id=>!(state.journey.tier==='gold'&&id==='rm')).map(channelName).join(' · '))+' · '+T('toValidate')],[T('advantage'),E(p.advantage)],[T('standardValue'),E(p.standardValue)],[T('cardValue'),E(p.cardValue)],[T('partnerValue'),E(p.partnerValue)],[T('pricing'),p.pricing==null?T('dataRequired'):esc(p.pricing)],[T('conditions'),E(p.conditions)],[T('owner'),esc(ownerName(p.owner))+' · '+T('proposedOwner')],[T('questions'),E(p.questions)]])}<section class="detail-section"><h3>${T('pain')}</h3>${related.length?related.map(findingRow).join(''):`<p>${T('dataRequired')}</p>`}</section><section class="detail-section"><h3>${T('source')}</h3>${linkedSources(p.sourceIds)}</section>${linkedGaps(p.stageIds.flatMap(s=>by('scenes',s)?.gapIds||[]))}${btn('edit-record',T('edit'),'button secondary',`data-collection="products" data-id="${p.id}"`)}`);}
function showProducts(){openDialog(T('products'),`<p class="notice">${T('valueWarning')}</p><p>${E(by('tiers',state.journey.tier).focus)}</p><div class="shelf-list">${data.products.map(p=>`<button data-action="product" data-id="${p.id}"><span>${E(p.title)}</span>${badge(B(p.valueLabel),'outlined')}<span>→</span></button>`).join('')}</div>${btn('export-csv',T('exportCsv'),'button secondary','data-collection="products"')}`);}
function showBenefitChecklist(){const b=data.benefits.find(b=>b.tierScope.includes(state.journey.tier));openDialog(T('questionnaire'),`<p class="notice">${T('valueWarning')}</p>${b?`<h3>${E(b.title)}</h3>${badge(B(b.valueLabel),'outlined')}<p>${E(b.summary)}</p>${metaDL([[T('entitled'),T('toValidate')],[T('provider'),E(b.provider)],[T('conditions'),T('dataRequired')],[T('activation'),T('toValidate')],[T('explained'),T('dataRequired')],[T('recovery'),esc(ownerName(b.owner))]])}${linkedSources(b.sourceIds)}`:`<p>${T('ownerConfirmed')}</p>`}${linkedGaps(['G12'])}`);}
function showChannel(id){const c=by('touchpoints',id);if(!c)return;const na=state.journey.tier==='gold'&&(id==='rm'||id==='whatsapp');openDialog(L(c.title),`${na?`<p class="notice">${T('goldNoRm')}</p>`:''}<div class="detail-badges">${statusBadge(c.validationStatus)}${badge(na?T('na'):c.availability==='reported'?T('reportedPractice'):B(c.availability),'outlined')}</div>${metaDL([[T('purpose'),B(c.purpose)],[T('scope'),esc(c.tierScope.map(tierName).join(' · '))],[T('authentication'),E(c.recognition)+' '+E(c.authentication)],[T('services'),E(c.services)],[T('branchDependencies'),E(c.branchDependencies)],[T('handoff'),E(c.handoff)],[T('owner'),esc(ownerName(c.owner))],[T('period'),esc(c.sourcePeriod)],[T('questions'),E(c.questions)]])}${measureBlock(L(c.measures))}${linkedSources(c.sourceIds)}${btn('edit-record',T('edit'),'button secondary',`data-collection="touchpoints" data-id="${id}"`)}`);}
function showChannelAtlas(){openDialog(T('moreChannels'),`<p class="tiny">${T('channelStatus')} ≠ ${T('capability')}</p><div class="channel-atlas">${data.touchpoints.map(c=>`<button data-action="channel" data-id="${c.id}"><strong>${E(c.title)}</strong><span>${B(c.purpose)}</span>${badge(state.journey.tier==='gold'&&c.id==='rm'?T('na'):c.availability==='reported'?T('reportedPractice'):B(c.availability),'outlined')}</button>`).join('')}</div>`);}
function showSceneOwner(){const ids=[...new Set([...sceneFindings(state.journey.stage).map(f=>f.proposedOwner),...by('scenes',state.journey.stage).gapIds.map(id=>by('gaps',id)?.owner)])].filter(Boolean);openDialog(T('whoOwns'),`<p class="notice">${T('governanceNote')}</p>${ids.map(id=>{const o=by('owners',id);return `<section class="owner-detail"><h3>${E(o.name)}</h3><p>${E(o.contribution)}</p><p>${T('spoc')}: ${esc(o.spoc||T('unassigned'))}</p>${btn('edit-record',T('edit')+' →','text-button',`data-collection="owners" data-id="${id}"`)}</section>`}).join('')}${btn('nav',T('governance')+' →','button secondary','data-view="governance"')}`);}
function editRecord(collection,id,isNew=false,recordOverride=null,gapId=null){const list=collection==='phases'?data.plan.phases:data[collection];if(!list)return;const r=recordOverride||(isNew?newRecord(collection,data):structuredClone(list.find(r=>r.id===id)));if(!r)return;openDialog(T(isNew?'addRecord':'edit')+' · '+(collection==='phases'?T('phaseGates'):collectionLabel(collection)),recordForm(r,collection,data,state.lang,isNew),{collection,original:r,isNew,gapId});}
function exportDataset(){download('wessam-360-presentation.json',JSON.stringify(data,null,2));}
function exportCsv(collection){let rows=data[collection]||[];if(collection==='products')rows=data.products.flatMap(p=>data.tiers.map(tier=>({...flattenRecord(p),tier:tier.id,availability:p.availability[tier.id],valueAttribution:p.valueLabel,confirmedWessamSpecific:p.valueLabel==='confirmed'&&p.validationStatus==='validated'})));else rows=rows.map(flattenRecord);download(`wessam-360-${collection}.csv`,csv(rows),'text/csv;charset=utf-8');}
function resetAll(withExport=false){if(withExport)exportDataset();storage.remove('w360-dataset-v1');storage.remove('w360-session-v1');data=createSeed();const lang=state.lang;state={lang,view:'home',journey:freshJourney(),presenter:null,menu:false,filter:{},sourceTab:false,editorCollection:'findings'};lastMapPosition=null;closeDialog();render();toast(T('resetOk'));}
function startJourney(){state.journey={...freshJourney(),tier:state.journey.tier,profiles:state.journey.profiles,starting:state.journey.starting,mode:state.journey.mode,started:true};state.view='journey';state.presenter=null;lastMapPosition=null;visitStage();render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#scene-heading')?.focus({preventScroll:true});}
function startGuided(){if(state.view!=='journey')state.journey={...freshJourney(),profiles:state.journey.profiles,started:true};state.view='journey';state.presenter={index:0,paused:false};applyKickoff();}
function applyKickoff(){const slide=data.kickoff[state.presenter.index];state.journey=changeTier(state.journey,slide.tier);state.journey.stage=slide.stageId;state.journey.result=null;state.journey.started=true;visitStage();render();window.scrollTo({top:0,behavior:'instant'});}
function advanceKickoff(delta){if(state.presenter.paused)return;state.journey=commitResult(state.journey);state.presenter.index=Math.max(0,Math.min(data.kickoff.length-1,state.presenter.index+delta));applyKickoff();}
function goStage(stage){if(!by('stages',stage))return;state.journey={...state.journey,stage,result:null,ending:null,started:true};state.view='journey';visitStage();render();document.querySelector('#scene-heading')?.focus({preventScroll:true});if(matchMedia('(max-width:800px)').matches)document.querySelector('.scene-panel')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function buildPrint(){const positive=data.findings.filter(f=>f.positiveOrPain==='positive');document.querySelector('#print-summary').innerHTML=`<h1>Wessam 360° — ${T('tagline')}</h1><p>${T('privacy')}</p><h2>${T('tierCompare')}</h2>${tierComparison()}<h2>${T('evidence')}</h2><p>${data.findings.length} ${T('findings')} · ${T('interviews')} · ${T('painInventory')}</p><p>${T('auditNote')} ${T('loadedNote')}</p><h2>${T('reveals')}</h2><ul>${['F01','F03','F18','F22','F29','F32','F36'].map(id=>by('findings',id)).filter(Boolean).map(f=>{return `<li>${E(f.summary)} <small>(${f.sourceId}; ${f.sourcePeriod}; ${B(f.validationStatus)})</small></li>`}).join('')}</ul><h2>${T('positiveEvidence')}</h2><ul>${positive.map(f=>`<li>${E(f.summary)} (${f.sourceId}, ${f.sourcePeriod})</li>`).join('')}</ul><h2>${T('limits')}</h2><p>${T('loadedNote')} ${E(by('findings','F43')?.summary)}</p><h2>${T('gaps')}</h2><ul>${data.gaps.map(g=>`<li>${g.id} — ${E(g.title)} · ${esc(ownerName(g.owner))} · ${esc(g.spoc||T('unassigned'))}</li>`).join('')}</ul><h2>${T('decisionLog')}</h2><ol>${data.decisions.map(d=>`<li>${E(d.title)} — ${esc(d.decision||T('tbd'))}</li>`).join('')}</ol><h2>${T('outputs')}</h2><p>${E(data.plan.outputs)}</p><h2>${T('successMeasures')}</h2><p>${T('measureList')} ${T('baselineLabel')}: ${T('dataRequired')} · ${T('target')}: ${T('dataRequired')}</p><p>${T('proposal')} · ${T('noPrivate')}</p>`;}
document.addEventListener('click',async event=>{
 if(event.target.closest('#skip-link')){event.preventDefault();document.querySelector('#main')?.focus();return;}
 const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const a=button.dataset.action;const d=button.dataset;
 if(state.presenter?.paused&&['choose','continue','stage','revisit','back'].includes(a))return;
 try{
 switch(a){
 case 'nav':closeDialog();state.view=d.view;if(d.view==='journey'){state.journey.started=true;visitStage()}state.menu=false;render();document.querySelector('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});break;
 case 'menu':state.menu=!state.menu;render();break;
 case 'language':state.lang=state.lang==='en'?'ar':'en';if(dialog.open)closeDialog();render('language-toggle');break;
 case 'select-tier':state.journey=changeTier(state.journey,d.tier);render();break;
 case 'compare-tier':state.journey=changeTier(state.journey,d.tier);visitStage();render();document.querySelector('#scene-heading')?.focus({preventScroll:true});break;
 case 'start':closeDialog();startJourney();break;
 case 'explore-all':state.journey.started=true;state.view='journey';state.journey.narrative=true;visitStage();render();break;
 case 'guided':closeDialog();startGuided();break;
 case 'choose':state.journey.result=resolveAction(data,state.journey,d.id);render();document.querySelector('.scene-result')?.focus({preventScroll:true});document.querySelector('.scene-result')?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;
 case 'continue':if(state.presenter){advanceKickoff(1);break}state.journey=commitResult(state.journey);state.journey.stage=nextStage(data,state.journey.tier,state.journey.stage);visitStage();render();document.querySelector('#scene-heading')?.focus({preventScroll:true});break;
 case 'try-again':state.journey.result=null;render();document.querySelector('[data-action="choose"]')?.focus({preventScroll:true});break;
 case 'back':state.journey=goBack(state.journey);visitStage();render();break;
 case 'stage':goStage(d.stage);break;
 case 'goto-scene':closeDialog();goStage(d.stage);break;
 case 'revisit':{const idx=Number(d.index);const old=state.journey.trail[idx];if(!old)break;state.journey={...state.journey,tier:old.tier,stage:old.stage,channel:old.previousChannel,trail:state.journey.trail.slice(0,idx),result:null,ending:null};render();break;}
 case 'map-view':state.journey.narrative=false;render();break;
 case 'narrative-view':state.journey.narrative=true;render();break;
 case 'zoom-in':state.journey.zoom=Math.min(1.5,Math.round((state.journey.zoom+.1)*10)/10);render();break;
 case 'zoom-out':state.journey.zoom=Math.max(1,Math.round((state.journey.zoom-.1)*10)/10);render();break;
 case 'zoom-reset':state.journey.zoom=1;render();break;
 case 'ending':state.journey.ending=d.ending;render();toast(T('endingNote'));break;
 case 'scene-evidence':showSceneEvidence();break;
 case 'scene-gaps':showSceneGaps(d.stage||state.journey.stage);break;
 case 'scene-owner':showSceneOwner();break;
 case 'finding':showFinding(d.id);break;
 case 'source':showSource(d.id);break;
 case 'gap':showGap(d.id);break;
 case 'products':showProducts();break;
 case 'product':showProduct(d.id);break;
 case 'benefit-checklist':showBenefitChecklist();break;
 case 'channel-atlas':showChannelAtlas();break;
 case 'channel':showChannel(d.id);break;
 case 'branch-channel':showChannel('wessam-area');break;
 case 'tier-comparison':openDialog(T('tierCompare'),tierComparison());break;
 case 'jump-scene':document.querySelector('.scene-panel')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#scene-heading')?.focus({preventScroll:true});break;
 case 'trail':document.querySelector('#journey-trail')?.scrollIntoView({block:'center',behavior:'smooth'});document.querySelector('#journey-trail')?.focus({preventScroll:true});break;
 case 'attribution':openDialog(T('attribution'),`<div class="attribution-case">${art('branch','elite')}<p class="detail-lead">${T('attributionBody')}</p>${linkedGaps(['G11'])}<p class="notice">${T('fiction')}</p></div>`);break;
 case 'positive-filter':state.filter={polarity:'positive'};state.sourceTab=false;render();break;
 case 'clear-filters':state.filter={};render();break;
 case 'findings-tab':state.sourceTab=false;render();break;
 case 'sources-tab':state.sourceTab=true;render();break;
 case 'export-json':exportDataset();break;
 case 'export-csv':exportCsv(d.collection);break;
 case 'edit-record':editRecord(d.collection,d.id);break;
 case 'add-record':editRecord(d.collection,null,true);break;
 case 'edit-phase':editRecord('phases',d.id);break;
 case 'add-evidence':editRecord('evidence',null,true,null,d.gap);break;
 case 'reset-data':openDialog(T('resetTitle'),`<p>${T('resetNote')}</p><div class="reset-options">${btn('export-reset',T('exportReset'),'button primary')}${btn('confirm-reset',T('confirmReset'),'button secondary')}${btn('close',T('cancel'),'text-button')}</div>`);break;
 case 'export-reset':resetAll(true);break;
 case 'confirm-reset':resetAll();break;
 case 'close':closeDialog();break;
 case 'print':buildPrint();window.print();break;
 case 'share':{const url=location.origin+location.pathname+shareHash(state);try{await navigator.clipboard.writeText(url);toast(T('copyOk'))}catch{openDialog(T('copyFallback'),`<label>${T('share')}<input readonly value="${esc(url)}" dir="ltr"></label><p>${T('localNote')}</p>`)}break;}
 case 'kick-next':advanceKickoff(1);break;
 case 'kick-prev':advanceKickoff(-1);break;
 case 'kick-pause':state.presenter.paused=!state.presenter.paused;render();break;
 case 'kick-restart':state.presenter={index:0,paused:false};applyKickoff();break;
 case 'exit-guided':state.presenter=null;render();break;
 case 'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast(T('fullscreenUnavailable'))}break;
 }
 }catch(error){toast((state.lang==='ar'?'تعذر إتمام الإجراء: ':'Unable to complete: ')+error.message)}
});
document.querySelector('#dialog-close').addEventListener('click',closeDialog);
dialog.addEventListener('cancel',()=>{dialogContext=null;});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
document.addEventListener('change',async event=>{const el=event.target;
 if(el.id==='tier-switch'){state.journey=changeTier(state.journey,el.value);visitStage();render('tier-switch')}
 if(el.id==='experience-mode'){state.journey.mode=el.value==='future'?'future':'current';state.journey.result=null;render('experience-mode')}
 if(el.id==='kick-index'&&state.presenter){state.presenter.index=Number(el.value);applyKickoff()}
 if(el.dataset.profile){if(el.dataset.profile==='starting')state.journey.starting=el.value;else{const tier=state.journey.tier;state.journey.profiles[tier]={...(state.journey.profiles[tier]||{}),[el.dataset.profile]:el.value}}persist()}
 if(el.dataset.filter){state.filter[el.dataset.filter]=el.value;render('filter-'+el.dataset.filter)}
 if(el.id==='editor-collection'){state.editorCollection=el.value;render('editor-collection')}
 if(el.id==='import-file'&&el.files?.[0]){try{if(el.files[0].size>2000000)throw new Error('Maximum import size is 2 MB.');const incoming=parseDataset(await el.files[0].text());data=incoming;state.journey.result=null;if(!by('stages',state.journey.stage))state.journey.stage='discover';persist(true);render();toast(T('imported'))}catch(error){toast((state.lang==='ar'?'لم يُستورد الملف: ':'Import rejected: ')+error.message)}el.value='';}
});
document.addEventListener('input',event=>{if(event.target.id==='record-json')event.target.dataset.changed='true';if(event.target.id==='record-search'){const el=event.target,pos=el.selectionStart;state.filter.search=el.value;render('record-search');document.querySelector('#record-search').setSelectionRange(pos,pos);}});
document.addEventListener('submit',event=>{if(event.target.id!=='record-form')return;event.preventDefault();const ctx=dialogContext;if(!ctx)return;try{const next=readRecordForm(event.target,ctx.original);const draft=structuredClone(data);const list=ctx.collection==='phases'?draft.plan.phases:draft[ctx.collection];if(ctx.isNew)list.push(next);else{const index=list.findIndex(r=>r.id===ctx.original.id);list[index]=next;}
 if(ctx.gapId){const gap=draft.gaps.find(g=>g.id===ctx.gapId);if(gap&&!gap.evidenceIds.includes(next.id))gap.evidenceIds.push(next.id)}validateDataset(draft);data=draft;persist(true);closeDialog();render();toast(T('saveOk'));}catch(error){document.querySelector('#form-error').textContent=(state.lang==='ar'?'صيغة غير صالحة: ':'Validation failed: ')+error.message;}});
window.addEventListener('hashchange',()=>{const p=parseHash(location.hash,data);state.lang=p.lang;state.view=p.view;state.journey=changeTier(state.journey,p.tier);state.journey.stage=p.stage;state.journey.mode=p.mode;state.journey.result=null;state.presenter=null;render();});
document.addEventListener('keydown',event=>{if(!state.presenter||dialog.open||event.ctrlKey||event.metaKey||event.altKey||/INPUT|TEXTAREA|SELECT|BUTTON/.test(event.target.tagName))return;if(event.key==='ArrowRight'){event.preventDefault();advanceKickoff(state.lang==='ar'?-1:1)}if(event.key==='ArrowLeft'){event.preventDefault();advanceKickoff(state.lang==='ar'?1:-1)}});
render();
if(recovery)toast(state.lang==='ar'?'تعذر قراءة البيانات المحفوظة؛ استُعيدت بيانات العرض الأصلية.':'Saved data could not be read; the original demonstration dataset was restored.');
if(!storage.available)toast(T('memoryOnly'));
